document.addEventListener('DOMContentLoaded',()=>{const audio=document.querySelector('#bgm'),button=document.querySelector('#music-toggle'),status=document.querySelector('#music-status');audio.volume=.25;audio.loop=true;const sync=()=>{button.textContent=audio.paused?'▷ 开始播放':'Ⅱ 暂停播放';button.setAttribute('aria-pressed',String(!audio.paused))};button.onclick=async()=>{if(!audio.paused){audio.pause();return}status.textContent='正在载入录音…';try{await audio.play();status.textContent=''}catch(e){status.textContent='录音暂时无法播放，请使用上方的原始录音链接收听。';sync()}};audio.addEventListener('play',sync);audio.addEventListener('pause',sync);audio.addEventListener('ended',sync);audio.addEventListener('error',()=>{status.textContent='录音载入失败，可展开来源信息前往原始页面收听。';sync()});audio.addEventListener('playing',()=>status.textContent='')});
